1	import type {AddressInfo} from 'node:net';
2	import {WebSocket} from 'ws';
3	import type {Express} from 'express';
4	import {createServer} from './createServer.js';
5	import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
6	import {answeringOrchestrator, delegatingStore, useTestLifecycle} from './wsTestSupport.js';
7	import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
8	import type {SessionCursor, SessionListOptions, SessionStore, SessionSummary} from '../types/sessionStore.js';
9	import {setLogger} from '../shared/logger.js';
10	
11	// Real upgrades over a real socket: what the list_sessions frame answers is the contract, and no double can observe it.
12	
13	interface Frame {
14	  type: string;
15	  sessionId?: string;
16	  sessions?: Array<{sessionId: string; createdAt: string; updatedAt: string; entryCount: number}>;
17	  code?: string;
18	  message?: string;
19	}
20	
21	const servers: Array<ReturnType<typeof createServer>> = [];
22	const clients: WebSocket[] = [];
23	const logLines: Array<{level: string; category: string; message: string; fields?: Record<string, unknown>}> = [];
24	
25	beforeEach(() => {
26	  logLines.length = 0;
27	  const record = (level: string) => (category: string, message: string, fields?: Record<string, unknown>) =>
28	    void logLines.push({level, category, message, fields});
29	  setLogger({debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')});
30	});
31	
32	useTestLifecycle(servers, clients);
33	
34	afterEach(() => {
35	  setLogger();
36	});
37	
38	const startEngine = async (store: SessionStore, userId: string | number = 'u1') => {
39	  const hal = createServer({
40	    app: (() => undefined) as unknown as Express,
41	    wsAuth: async () => ({id: userId}),
42	    sessionStore: store,
43	    orchestrator: answeringOrchestrator,
44	  });
45	  await hal.start(0);
46	  servers.push(hal);
47	  const {port} = hal.server.address() as AddressInfo;
48	  return `ws://127.0.0.1:${port}/hal/ws`;
49	};
50	
51	const askAfterConnect = async (url: string, outbound: unknown): Promise<{connected: Frame; frames: Frame[]}> => {
52	  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
53	  clients.push(client);
54	  const frames: Frame[] = [];
55	  let connected: Frame = {type: ''};
56	  await new Promise<void>(resolve => {
57	    client.on('message', raw => {
58	      const frame = JSON.parse(String(raw)) as Frame;
59	      if (frame.type === 'pong') {
60	        resolve();
61	        return;
62	      }
63	      if (frame.type !== 'connected') {
64	        frames.push(frame);
65	        return;
66	      }
67	      connected = frame;
68	      client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
69	      client.send(JSON.stringify({type: 'ping', timestamp: 1}));
70	    });
71	  });
72	  return {connected, frames};
73	};
74	
75	describe('listing conversations over the WebSocket protocol', () => {
76	  it('answers list_sessions for the authenticated user with ISO dates, forwarding limit and before while ignoring any client userId', async () => {
77	    const inner = new InMemorySessionStore();
78	    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
79	    const summaries: SessionSummary[] = [
80	      {
81	        sessionId: 's2',
82	        createdAt: new Date('2026-01-01T00:00:00.000Z'),
83	        updatedAt: new Date('2026-01-01T00:02:00.000Z'),
84	        entryCount: 4,
85	      },
86	    ];
87	    const store: SessionStore = {
88	      ...delegatingStore(inner),
89	      listFor: (userId, options) => {
90	        seen.push({userId, options});
91	        return summaries;
92	      },
93	    };
94	    const url = await startEngine(store, 'u1');
95	    const before: SessionCursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
96	
97	    const {frames} = await askAfterConnect(url, {type: 'list_sessions', limit: 10, before, userId: 'u2'});
98	
99	    expect({seen, frames}).toEqual({
100	      seen: [{userId: 'u1', options: {limit: 10, before}}],
101	      frames: [
102	        {
103	          type: 'session_list',
104	          sessions: [
105	            {
106	              sessionId: 's2',
107	              createdAt: '2026-01-01T00:00:00.000Z',
108	              updatedAt: '2026-01-01T00:02:00.000Z',
109	              entryCount: 4,
110	            },
111	          ],
112	        },
113	      ],
114	    });
115	  });
116	
117	  it('answers an empty session_list when the store has no listFor, and SERVER_ERROR with a ws error log when listFor throws', async () => {
118	    const inner = new InMemorySessionStore();
119	    const withoutList = await startEngine(delegatingStore(inner));
120	    const failingList = await startEngine({
121	      ...delegatingStore(inner),
122	      listFor: () => Promise.reject(new Error('database offline')),
123	    });
124	
125	    const unimplemented = await askAfterConnect(withoutList, {type: 'list_sessions'});
126	    const failed = await askAfterConnect(failingList, {type: 'list_sessions'});
127	
128	    expect({
129	      unimplemented: unimplemented.frames,
130	      failed: failed.frames.map(frame => ({type: frame.type, code: frame.code})),
131	      logged: logLines.filter(line => line.level === 'error' && line.category === 'ws'),
132	    }).toEqual({
133	      unimplemented: [{type: 'session_list', sessions: []}],
134	      failed: [{type: 'error', code: 'SERVER_ERROR'}],
135	      logged: [
136	        {
137	          level: 'error',
138	          category: 'ws',
139	          message: expect.any(String),
140	          fields: expect.objectContaining({userId: 'u1', error: 'database offline'}),
141	        },
142	      ],
143	    });
144	  });
145	
146	  it('accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor', async () => {
147	    const inner = new InMemorySessionStore();
148	    let calls = 0;
149	    const store: SessionStore = {
150	      ...delegatingStore(inner),
151	      listFor: () => {
152	        calls += 1;
153	        return [];
154	      },
155	    };
156	    const url = await startEngine(store);
157	    const badFrames = [
158	      {type: 'list_sessions', limit: 'ten'},
159	      {type: 'list_sessions', limit: -1},
160	      {type: 'list_sessions', limit: 1.5},
161	      {type: 'list_sessions', before: 'not-an-object'},
162	      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
163	      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
164	      {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
165	      {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}},
166	    ];
167	
168	    const codes: Array<string | undefined> = [];
169	    for (const bad of badFrames) {
170	      const {frames} = await askAfterConnect(url, bad);
171	      codes.push(frames[0]?.code);
172	    }
173	    const {frames: accepted} = await askAfterConnect(url, {type: 'list_sessions'});
174	
175	    expect({codes, accepted, calls}).toEqual({
176	      codes: Array(badFrames.length).fill('INVALID_MESSAGE'),
177	      accepted: [{type: 'session_list', sessions: []}],
178	      calls: 1,
179	    });
180	  });
181	});
182

