function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const limitError = validateLimitField(message.limit);
  if (limitError) return limitError;

  const beforeError = validateBeforeField(message.before);
  if (beforeError) return beforeError;

  const before =
    message.before === undefined ? undefined : formatBeforeField(message.before as Record<string, unknown>);

